# V124: cada lote vuelve al catálogo y espera a que React reconstruya
# las filas. Tras un borrado masivo Wallapop a veces deja la ruta cargada
# pero el listado vacío durante unos segundos.
for intento in range(4):
    page.goto(destino, wait_until='domcontentloaded', timeout=45000)
    page.wait_for_timeout(1800 + intento*700)
    try:
        page.wait_for_load_state('networkidle', timeout=5000)
    except Exception:
        pass
    try:
        if page.locator('a[href*="/item/"]').count()>0:
            break
    except Exception:
        pass
    if intento<3:
        try: page.reload(wait_until='domcontentloaded', timeout=45000)
        except Exception: pass
        page.wait_for_timeout(1200)

if marcados==0:
    # V124: recuperación específica entre lotes. La vista del catálogo
    # puede quedar virtualizada/vacía después de confirmar el lote anterior.
    for intento in range(3):
        if stop.is_set(): raise Cancelado()
        try:
            page.goto('https://es.wallapop.com/app/catalog/published', wait_until='domcontentloaded', timeout=45000)
            page.wait_for_timeout(2200 + intento*900)
            page.evaluate('window.scrollTo(0,0)')
            page.wait_for_timeout(500)
            filas=_filas_catalogo(page)
            if filas:
                # Reiniciamos la selección completa sobre el DOM recién reconstruido.
                return seleccionar_lote(page, cantidad, stop, evento)
        except Cancelado:
            raise
        except Exception:
            pass
    raise RuntimeError('No pude localizar las filas de tus productos en el catálogo de Wallapop después de recargarlo.')
